function field(label,name,val='',type='text') { const numeric=type==='number'?(name==='year'?'step="1" inputmode="numeric"':/qty|quantity/.test(name)?'step="0.001" inputmode="decimal"':'step="0.01" inputmode="decimal"'):'';return `<label class="field"><span>${esc(label)}</span><input name="${esc(name)}" type="${type}" ${numeric} value="${esc(val)}"></label>`; }
function submitForm(endpoint,method,then){return async e=>{e.preventDefault();try{const body=Object.fromEntries(new FormData(e.target));const epoch=navigationEpoch,result=await api(endpoint,{method,body:JSON.stringify(body)},{form:e.target});if(epoch!==navigationEpoch)return;savedForm(e.target);await then(result)}catch(err){alert(err.message)}};}
function addressForm(c={}){
 const inp=(label,key,value='',required=false)=>`<label class="field"><span>${label}</span><input name="${key}" value="${esc(value)}" ${required?'required':''} autocomplete="${key==='address_line1'?'address-line1':key==='address_line2'?'address-line2':key==='city'?'address-level2':key==='state'?'address-level1':key==='postal_code'?'postal-code':'off'}"></label>`;
 const same=Number(c.billing_same_as_service??1)!==0;
 return `<fieldset class="address-fieldset"><legend>Customer / mailing address</legend><div class="form-grid">${inp('Street address','address_line1',c.address_line1||c.address||'',true)}${inp('Apartment / Suite','address_line2',c.address_line2||'')}${inp('City','city',c.city||'',true)}${inp('State','state',c.state||'AZ',true)}${inp('ZIP / Postal code','postal_code',c.postal_code||'',true)}</div></fieldset><label class="check-row"><input type="checkbox" name="billing_same_as_service" value="true" ${same?'checked':''}> Billing address same as customer address</label><fieldset class="address-fieldset billing-address" ${same?'hidden':''}><legend>Separate billing address</legend><div class="form-grid">${inp('Billing street','billing_address_line1',c.billing_address_line1||'')}${inp('Apartment / Suite','billing_address_line2',c.billing_address_line2||'')}${inp('Billing city','billing_city',c.billing_city||'')}${inp('Billing state','billing_state',c.billing_state||'AZ')}${inp('Billing ZIP','billing_postal_code',c.billing_postal_code||'')}</div></fieldset>`;
}
function setupAddressForm(form){
 const toggle=form.elements.billing_same_as_service,area=form.querySelector('.billing-address');
 const sync=()=>{area.hidden=toggle.checked;for(const x of area.querySelectorAll('input'))x.required=!toggle.checked&&['billing_address_line1','billing_city','billing_state','billing_postal_code'].includes(x.name)};toggle.addEventListener('change',sync);sync();
}
function submitCustomerForm(form,endpoint,method,then){form.onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(form));b.billing_same_as_service=!!form.elements.billing_same_as_service.checked;try{const r=await api(endpoint,{method,body:JSON.stringify(b)},{form});await then(r)}catch(err){alert(err.message)}};setupAddressForm(form)}
